use qop_wire::*;use qop_wire::extension::*;use ed25519_dalek::SigningKey;
#[test]fn integration(){let k=SigningKey::from_bytes(&[1;32]);let w=SigningKey::from_bytes(&[2;32]);let p=[3;24];let id=[4;32];let mut l=Ledger::new(k.verifying_key(),p);let mut prev=GENESIS;let mut frames=vec![];let mut cps=vec![Checkpoint::sign(id,&l.mmr,&w)];for i in 0..65{let f=mint(&k,i,i,i,1,[5;32],prev,p);assert_eq!(decode_json(&json(&f)),Some(f));assert!(decode_json(&(json(&f)+" ")).is_none());assert!(l.append(&f));prev=f[104..136].try_into().unwrap();frames.push(f);cps.push(Checkpoint::sign(id,&l.mmr,&w));}for i in 0..=65{let proof=consistency(&l.mmr,i).unwrap();assert!(verify_consistency(&cps[i],&cps[65],&proof,id,&w.verifying_key()));let mut bad=cps[65].clone();bad.root[0]^=1;assert!(!verify_consistency(&cps[i],&bad,&proof,id,&w.verifying_key()));}let path=std::env::temp_dir().join(format!("qop-v02-{}",std::process::id()));let _=std::fs::remove_file(&path);{let mut d=Durable::open(&path,k.verifying_key(),p).unwrap();for f in &frames{d.append(f).unwrap();}}assert_eq!(Durable::open(&path,k.verifying_key(),p).unwrap().state(),Some((65,l.mmr.root())));use std::io::Write;std::fs::OpenOptions::new().append(true).open(&path).unwrap().write_all(&[1]).unwrap();assert!(Durable::open(&path,k.verifying_key(),p).is_err());std::fs::remove_file(path).unwrap();let c=Clock::sign(id,7,100,2,&w);assert!(clock_ok(&c,id,7,101,3,&w.verifying_key()));assert!(!clock_ok(&c,id,8,101,3,&w.verifying_key()));assert!(!clock_ok(&c,id,7,110,3,&w.verifying_key()));let mut cih=Cih{next_epoch:0,energy:k.verifying_key(),compute:w.verifying_key(),policy:p};let a=mint(&k,0,99,100,1,[5;32],GENESIS,p);let b=mint(&w,0,99,101,1,[6;32],GENESIS,p);assert!(cih.settle(0,&a,&a,101,2).is_none());assert!(cih.settle(0,&a,&b,101,2).is_some());assert!(cih.settle(0,&a,&b,101,2).is_none());}
